package com.jobtracker.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.security.Key; import java.util.*;
@Service public class JwtService { private final Key key; private final long exp; public JwtService(@Value("${app.jwt.secret}")String s,@Value("${app.jwt.expiration-ms}")long e){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));exp=e;} public String create(String email){return Jwts.builder().subject(email).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+exp)).signWith(key).compact();} public String email(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();} public boolean valid(String t){try{email(t);return true;}catch(Exception e){return false;}} }